commands:
pwsh -NoProfile -Command '
$files = @("api/_lib/pantry-store.ps1","api/_lib/pantry-render.ps1","podex.ps1")
foreach ($f in $files) {
  $errs = $null
  [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$null, [ref]$errs)
  if ($errs) { Write-Host "PARSE ERRORS in $f"; $errs | ForEach-Object { Write-Host $_.Message } } else { Write-Host "OK $f" }
}'

pwsh -NoLogo -NoProfile -Command '
Import-Module PSScriptAnalyzer -ErrorAction SilentlyContinue
$ex = @("PSUseBOMForUnicodeEncodedFile","PSUseShouldProcessForStateChangingFunctions","PSUseSingularNouns")
foreach ($f in @("./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1","./podex.ps1")) {
  Invoke-ScriptAnalyzer -Path $f | Where-Object { $_.RuleName -notin $ex } |
    ForEach-Object { Write-Host "$($_.Severity) $($_.RuleName) $f :$($_.Line)" }
}
Write-Host "analyze-done"'
